import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.CLq81i8L.js";const g=JSON.parse('{"title":"AI 架构文档","description":"","frontmatter":{},"headers":[],"relativePath":"ai/architecture.md","filePath":"ai/architecture.md","lastUpdated":1785288787000}'),r={name:"ai/architecture.md"};function s(n,t,c,l,i,p){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="ai-架构文档" tabindex="-1">AI 架构文档 <a class="header-anchor" href="#ai-架构文档" aria-label="Permalink to &quot;AI 架构文档&quot;">​</a></h1><blockquote><p><code>ai/</code> 项目整体架构：Chat LangGraph 与 Agent Workflow 双引擎。<br><strong>三能力关系、JWT、凭证、开源小平台定位</strong>见 <a href="./platform.html">platform.md</a>。</p></blockquote><p><strong>文档版本</strong>：v7 (2026-07-13) — 去除旧架构引用，对齐当前实现</p><hr><h2 id="一、项目结构" tabindex="-1">一、项目结构 <a class="header-anchor" href="#一、项目结构" aria-label="Permalink to &quot;一、项目结构&quot;">​</a></h2><p><code>ai/</code> 为多包并列仓库（非 monorepo workspace），各子包独立 <code>package.json</code>、独立构建与部署。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ai/</span></span>
<span class="line"><span>├── app/              @ai-app                         Vue 3 微前端：Chat、RAG、监控、工作流设计器、插件中心</span></span>
<span class="line"><span>├── shared/           @schema-platform/ai-shared       跨端类型、事件、Prompt、工作流域模型</span></span>
<span class="line"><span>└── docs/             本文档目录</span></span></code></pre></div><table tabindex="0"><thead><tr><th>包</th><th>消费者</th><th>职责</th></tr></thead><tbody><tr><td><code>@ai-app</code></td><td>shell（qiankun）</td><td>前端 UI：Chat、工作流设计器、执行监控、RAG、插件中心 <code>/plugins</code></td></tr><tr><td><code>@schema-platform/platform-shared/ai</code></td><td>app、server</td><td>事件协议、工具名、Prompt、工作流类型</td></tr></tbody></table><p><strong>依赖方向</strong>：<code>app → ai-shared + platform-shared</code>；<code>server → ai-shared</code>。</p><p><strong>插件中心</strong>：Expert / Skill / Tool / MCP 由 <code>server/config/plugins/</code> 分目录配置（见 <a href="./../ai/docs/plugin.html">plugin.md</a>），支持 <code>plugin:pack</code> / <code>plugin:install</code> 与 SIGHUP 热重载。</p><p><strong>同仓开发</strong>：<code>app/package.json</code> 通过 <code>file:../shared</code> 引用 ai-shared；Vite alias 可直连 shared 源码，改公共包后 dev/build 自动生效。</p><hr><h2 id="二、双-agent-系统" tabindex="-1">二、双 Agent 系统 <a class="header-anchor" href="#二、双-agent-系统" aria-label="Permalink to &quot;二、双 Agent 系统&quot;">​</a></h2><p>平台运行两套并行的 Agent 引擎，共享 MCP 工具注册表与 <code>@schema-platform/platform-shared/ai</code>，但执行模型不同：</p><table tabindex="0"><thead><tr><th>维度</th><th>Chat LangGraph</th><th>Agent Workflow DAG</th></tr></thead><tbody><tr><td>入口</td><td>AiChatView、editor/flow 嵌入</td><td>设计器、REST API、Webhook、Chat 选工作流</td></tr><tr><td>引擎</td><td><code>server/src/ai/graph/graph.ts</code></td><td><code>server/src/ai/services/agentWorkflowExecutor.ts</code></td></tr><tr><td>编排模型</td><td>LangGraph StateGraph + Checkpoint</td><td>n8n 风格顺序 DAG 遍历</td></tr><tr><td>状态持久化</td><td>LangGraph checkpointer</td><td>MongoDB <code>AgentWorkflowExecution</code></td></tr><tr><td>HITL</td><td>LangGraph <code>interrupt</code> / <code>chat:resume</code></td><td><code>hitl</code> 节点 + <code>POST .../resume</code></td></tr><tr><td>工具</td><td>MCP Bridge + LangGraph 专有工具</td><td>同上 + 内置 <code>http_request</code></td></tr><tr><td>文档</td><td><a href="./agent.html">agent.md</a></td><td><a href="./agent-workflow.html">agent-workflow.md</a></td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌─────────────────────────────────────┐</span></span>
<span class="line"><span>                    │     @schema-platform/ai-shared      │</span></span>
<span class="line"><span>                    │  events · toolNames · promptBuilder │</span></span>
<span class="line"><span>                    │  agentWorkflow · document           │</span></span>
<span class="line"><span>                    └─────────────────────────────────────┘</span></span>
<span class="line"><span>                           ▲                    ▲</span></span>
<span class="line"><span>                           │                    │</span></span>
<span class="line"><span>              ┌────────────┴──────┐   ┌────────┴────────────┐</span></span>
<span class="line"><span>              │  Chat LangGraph   │   │  Agent Workflow     │</span></span>
<span class="line"><span>              │  (对话式生成)      │   │  (可视化编排)        │</span></span>
<span class="line"><span>              └────────────┬──────┘   └────────┬────────────┘</span></span>
<span class="line"><span>                           │                    │</span></span>
<span class="line"><span>                           └────────┬───────────┘</span></span>
<span class="line"><span>                                    ▼</span></span>
<span class="line"><span>                         ┌─────────────────────┐</span></span>
<span class="line"><span>                         │  tools/registry.ts  │</span></span>
<span class="line"><span>                         │  MCP Bridge (5 服务) │</span></span>
<span class="line"><span>                         └─────────────────────┘</span></span></code></pre></div><hr><h2 id="三、chat-langgraph-架构" tabindex="-1">三、Chat LangGraph 架构 <a class="header-anchor" href="#三、chat-langgraph-架构" aria-label="Permalink to &quot;三、Chat LangGraph 架构&quot;">​</a></h2><h3 id="_3-1-编译图节点-当前代码" tabindex="-1">3.1 编译图节点（当前代码） <a class="header-anchor" href="#_3-1-编译图节点-当前代码" aria-label="Permalink to &quot;3.1 编译图节点（当前代码）&quot;">​</a></h3><p><code>server/src/ai/graph/graph.ts</code> 注册的节点：</p><table tabindex="0"><thead><tr><th>节点</th><th>职责</th></tr></thead><tbody><tr><td><code>router</code></td><td>显式模式路由、关键词多意图检测、任务链预建</td></tr><tr><td><code>requirementAnalyzer</code></td><td>v2：深度需求分析（默认开启）</td></tr><tr><td><code>requirementConfirm</code></td><td>v2：需求确认卡片（HITL）</td></tr><tr><td><code>taskPlanner</code></td><td>v2：任务规划，生成 task chain</td></tr><tr><td><code>taskChain</code></td><td>任务链推进、Agent 协作插入；写入 <code>session.currentExpertId</code></td></tr><tr><td><strong><code>pluginExpert</code></strong></td><td><strong>唯一专家执行节点</strong>（Registry prompt/tools + 领域上下文）</td></tr><tr><td><code>allTools</code></td><td>ToolNode 执行（带错误兜底）</td></tr><tr><td><code>afterTools</code></td><td>工具后处理、协作请求提取、上下文传递</td></tr><tr><td><code>summarizer</code></td><td>多步任务结果汇总</td></tr></tbody></table><p>专家解析与 session 同步：<code>graph/resolveGraphExpert.ts</code>。领域用户上下文（Schema/Flow/协作）：<code>graph/expertUserContext.ts</code>。</p><blockquote><p><strong>基线 1.0</strong>：已删除 <code>editor</code> / <code>flow</code> / <code>page</code> / <code>general</code> 图节点及 <code>*Agent.ts</code>；内置与第三方专家均走 <code>pluginExpert</code>。</p></blockquote><blockquote><p><strong>注意</strong>：<code>thinker</code>、<code>qualityCheck</code> 仅在 <code>events.ts</code> 类型中定义，<strong>未注册为图节点</strong>，服务端不发射对应事件。</p></blockquote><h3 id="_3-2-v2-默认流程" tabindex="-1">3.2 v2 默认流程 <a class="header-anchor" href="#_3-2-v2-默认流程" aria-label="Permalink to &quot;3.2 v2 默认流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>START</span></span>
<span class="line"><span>  → router</span></span>
<span class="line"><span>  → requirementAnalyzer</span></span>
<span class="line"><span>      ├─ (需确认) → requirementConfirm → taskPlanner</span></span>
<span class="line"><span>      └─ (跳过确认) ─────────────────────→ taskPlanner</span></span>
<span class="line"><span>  → taskPlanner → taskChain</span></span>
<span class="line"><span>  → taskChain → pluginExpert | summarizer</span></span>
<span class="line"><span>  → pluginExpert</span></span>
<span class="line"><span>      ├─ (有 tool_calls) → allTools → afterTools → taskChain | pluginExpert | summarizer</span></span>
<span class="line"><span>      └─ (无 tool_calls) → END 或 summarizer / taskChain</span></span>
<span class="line"><span>  → summarizer → END</span></span></code></pre></div><p><strong>环境变量</strong>：</p><table tabindex="0"><thead><tr><th>变量</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>AI_ENABLE_TASK_PLANNER</code></td><td><code>true</code></td><td>启用任务规划节点</td></tr></tbody></table><h3 id="_3-3-专家与插件中心" tabindex="-1">3.3 专家与插件中心 <a class="header-anchor" href="#_3-3-专家与插件中心" aria-label="Permalink to &quot;3.3 专家与插件中心&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td><strong>Registry 专家</strong></td><td><code>server/config/plugins/experts/*.json</code>，如 <code>platform.editor</code></td></tr><tr><td><strong><code>legacyAgentKey</code></strong></td><td>内置四专家的调度键（<code>editor</code>/<code>flow</code>/<code>page</code>/<code>general</code>），用于 task chain、协作、显式 <code>context.source</code>；<strong>不</strong>再对应独立图节点</td></tr><tr><td><strong><code>session.currentExpertId</code></strong></td><td>运行时权威专家 id；<code>pluginExpert</code> 据此执行</td></tr><tr><td><strong>System Prompt</strong></td><td><code>buildExpertSystemPrompt</code>（插件 <code>systemPrompt</code> + Skill）；<code>dynamicPrompt</code> 走 ai-shared <code>promptBuilder</code></td></tr><tr><td><strong>第三方专家</strong></td><td>仅加插件 JSON + pack，无需新增 <code>graph/*Agent.ts</code></td></tr></tbody></table><h3 id="_3-4-关键行为" tabindex="-1">3.4 关键行为 <a class="header-anchor" href="#_3-4-关键行为" aria-label="Permalink to &quot;3.4 关键行为&quot;">​</a></h3><ul><li><strong>显式模式</strong>：<code>context.source === editor|flow|page</code> 时跳过关键词猜测，直接进入对应专家</li><li><strong>多意图</strong>：router 检测「页面 + 表单/流程」组合时预建 task chain</li><li><strong>工具循环</strong>：每轮 Agent 最多 3 次 tool iteration；全局 <code>session.maxNodeExecutions</code> 防死循环</li><li><strong>协作</strong>：<code>request_collaboration</code> 工具 → <code>afterTools</code> 提取 → <code>taskChain</code> 插入协作步骤</li><li><strong>流式传输</strong>：WebSocket / Socket.IO，事件类型见 <a href="./events.html">events.md</a></li></ul><hr><h2 id="四、agent-workflow-架构-概要" tabindex="-1">四、Agent Workflow 架构（概要） <a class="header-anchor" href="#四、agent-workflow-架构-概要" aria-label="Permalink to &quot;四、Agent Workflow 架构（概要）&quot;">​</a></h2><p>可视化 DAG 编排系统，详见 <a href="./agent-workflow.html">agent-workflow.md</a>。</p><h3 id="_4-1-生命周期" tabindex="-1">4.1 生命周期 <a class="header-anchor" href="#_4-1-生命周期" aria-label="Permalink to &quot;4.1 生命周期&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>设计 (draftGraph) → 保存 (版本快照) → 发布 (publishedGraph + publishId) → 执行 → 监控</span></span></code></pre></div><h3 id="_4-2-节点分类-基线-1-0" tabindex="-1">4.2 节点分类（基线 1.0） <a class="header-anchor" href="#_4-2-节点分类-基线-1-0" aria-label="Permalink to &quot;4.2 节点分类（基线 1.0）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分类</th><th>节点类型</th></tr></thead><tbody><tr><td>触发</td><td><code>manual-trigger</code>、<code>webhook-trigger</code></td></tr><tr><td>AI</td><td><code>llm</code>、<code>document-parse</code>、<code>vision-analyze</code>、<code>conversation-memory</code>、<code>image-generate</code>、<code>ppt-generate</code></td></tr><tr><td>对话智能</td><td><code>intent-router</code>、<code>requirement-analyzer</code>、<code>task-planner</code>、<code>task-chain</code>、<code>collaboration-router</code>、<code>summarizer</code></td></tr><tr><td>专家</td><td><code>agent-intent</code>（自动路由）、<code>expert</code>（<code>expertId</code> → 插件中心）</td></tr><tr><td>工具</td><td><code>tool</code>（<code>toolName</code> → Registry / MCP）</td></tr><tr><td>逻辑</td><td><code>if</code>、<code>hitl</code>、<code>end</code></td></tr></tbody></table><p>Palette 专家与工具条目来自插件 Registry（<code>usePluginRegistry</code>），非硬编码 <code>agent-editor</code> / <code>tool-mcp-*</code>。</p><h3 id="_4-3-内置模板-16-个" tabindex="-1">4.3 内置模板（16 个） <a class="header-anchor" href="#_4-3-内置模板-16-个" aria-label="Permalink to &quot;4.3 内置模板（16 个）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>名称</th><th>触发</th></tr></thead><tbody><tr><td><code>blank</code></td><td>空白工作流</td><td>手动</td></tr><tr><td><code>document-summary</code></td><td>文档摘要</td><td>Webhook</td></tr><tr><td><code>doc-image-recognition</code></td><td>文档/图片识别</td><td>手动</td></tr><tr><td><code>intelligent-assistant</code></td><td>智能助手问答</td><td>手动</td></tr><tr><td><code>contract-extract</code></td><td>合同条款提取</td><td>Webhook</td></tr><tr><td><code>kb-faq</code></td><td>知识库 FAQ 生成</td><td>Webhook</td></tr><tr><td><code>http-notify</code></td><td>HTTP 回调通知</td><td>Webhook</td></tr><tr><td><code>rag-ingest-qa</code></td><td>RAG 入库质检</td><td>Webhook</td></tr><tr><td><code>multi-doc-batch</code></td><td>多文档批量处理</td><td>Webhook</td></tr><tr><td><code>smart-suggestions</code></td><td>智能建议</td><td>手动</td></tr><tr><td><code>smart-action-proposals</code></td><td>智能拟办</td><td>Webhook</td></tr><tr><td><code>image-text-generation</code></td><td>图文生成</td><td>手动</td></tr><tr><td><code>ppt-generation</code></td><td>PPT 生成</td><td>手动</td></tr><tr><td><code>image-analysis</code></td><td>图片智能分析</td><td>手动</td></tr><tr><td><code>chat-parity-assistant</code></td><td>智能助手 v2</td><td>手动</td></tr><tr><td><code>requirement-gated-build</code></td><td>需求门控构建</td><td>手动</td></tr></tbody></table><p>完整模板流程图见 <a href="./agent-workflow.html">agent-workflow.md</a>。定义与工厂函数在 <code>shared/platform-shared/ai/agentWorkflow.ts</code>。</p><h3 id="_4-4-前端路由" tabindex="-1">4.4 前端路由 <a class="header-anchor" href="#_4-4-前端路由" aria-label="Permalink to &quot;4.4 前端路由&quot;">​</a></h3><table tabindex="0"><thead><tr><th>路由</th><th>视图</th></tr></thead><tbody><tr><td><code>/workflows</code></td><td>工作流列表</td></tr><tr><td><code>/workflows/:id</code></td><td>设计器</td></tr><tr><td><code>/workflows/:id/executions</code></td><td>执行历史</td></tr><tr><td><code>/executions/:id</code></td><td>执行详情（节点级监控）</td></tr></tbody></table><p>Chat 可通过 <code>AgentWorkflowPicker</code> 选择已发布工作流作为对话后端。</p><hr><h2 id="五、工具层" tabindex="-1">五、工具层 <a class="header-anchor" href="#五、工具层" aria-label="Permalink to &quot;五、工具层&quot;">​</a></h2><h3 id="_5-1-三层工具" tabindex="-1">5.1 三层工具 <a class="header-anchor" href="#_5-1-三层工具" aria-label="Permalink to &quot;5.1 三层工具&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LangGraph Chat / Workflow Executor</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>         ▼</span></span>
<span class="line"><span>   tools/registry.ts</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>    ┌────┴────────────────┐</span></span>
<span class="line"><span>    ▼                     ▼</span></span>
<span class="line"><span> MCP Bridge            LangGraph 专有</span></span>
<span class="line"><span> (5 个 MCP Server)     (无前缀命名)</span></span></code></pre></div><p><strong>MCP 命名</strong>：<code>{domain}__{action}</code>（如 <code>schema__search</code>）</p><p><strong>LangGraph 专有</strong>（无 <code>__</code> 前缀）：<code>update_schema</code>、<code>generate_schema</code>、<code>update_flow</code>、<code>save_and_bind_schema</code>、<code>bind_schema_to_flow_node</code>、<code>request_collaboration</code>、<code>rag_index</code></p><p><strong>工作流专有</strong>：<code>http_request</code>（executor 内置，不在 MCP 注册表）</p><p>权威定义：<code>shared/platform-shared/ai/toolNames.ts</code>（MCP 规范名 <code>{domain}__{action}</code>，无旧名别名表）。</p><p>详见 <a href="./tool.html">tool.md</a>、<a href="./mcp.html">mcp.md</a>。</p><h3 id="_5-2-mcp-server-5-个" tabindex="-1">5.2 MCP Server（5 个） <a class="header-anchor" href="#_5-2-mcp-server-5-个" aria-label="Permalink to &quot;5.2 MCP Server（5 个）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Server</th><th>域前缀</th><th>职责</th></tr></thead><tbody><tr><td>schemaServer</td><td><code>schema__</code></td><td>Schema 搜索、详情、校验</td></tr><tr><td>flowServer</td><td><code>flow__</code></td><td>流程搜索、详情、校验、用户</td></tr><tr><td>widgetServer</td><td><code>widget__</code></td><td>组件目录查询与校验</td></tr><tr><td>ragServer</td><td><code>rag__</code></td><td>知识库检索</td></tr><tr><td>industryServer</td><td><code>industry__</code></td><td>行业模板搜索与校验</td></tr></tbody></table><p>Bridge 实现：<code>server/src/ai/mcp/bridge.ts</code>（InMemoryTransport → LangGraph StructuredTool）。</p><hr><h2 id="六、事件协议" tabindex="-1">六、事件协议 <a class="header-anchor" href="#六、事件协议" aria-label="Permalink to &quot;六、事件协议&quot;">​</a></h2><p>统一事件类型定义在 <code>shared/platform-shared/ai/events.ts</code>，经 WebSocket <code>chat:event</code> 推送到前端。</p><ul><li><strong>v1</strong>：文本流、Schema/Flow 生成、工具调用、任务链、HITL、done/error</li><li><strong>v2</strong>：需求分析、任务规划（已实现并发射）</li><li><strong>v2 预留</strong>：<code>thinker_*</code>、<code>quality_check_*</code>（类型已定义，图节点未实现）</li></ul><p>完整清单见 <a href="./events.html">events.md</a>。</p><hr><h2 id="七、服务端-api-概览" tabindex="-1">七、服务端 API 概览 <a class="header-anchor" href="#七、服务端-api-概览" aria-label="Permalink to &quot;七、服务端 API 概览&quot;">​</a></h2><p>Chat 与 Workflow 的 REST / WebSocket 端点由 <code>server/src/ai/</code> 提供（前端按已有接口适配，不修改 server 代码）。</p><h3 id="chat-websocket" tabindex="-1">Chat（WebSocket） <a class="header-anchor" href="#chat-websocket" aria-label="Permalink to &quot;Chat（WebSocket）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事件</th><th>方向</th><th>说明</th></tr></thead><tbody><tr><td><code>chat:send</code></td><td>Client → Server</td><td>发送消息</td></tr><tr><td><code>chat:event</code></td><td>Server → Client</td><td>流式事件</td></tr><tr><td><code>chat:resume</code></td><td>Client → Server</td><td>HITL 恢复</td></tr><tr><td><code>chat:cancel</code></td><td>Client → Server</td><td>取消生成</td></tr></tbody></table><h3 id="workflow-rest-api-ai" tabindex="-1">Workflow（REST，<code>/api/ai</code>） <a class="header-anchor" href="#workflow-rest-api-ai" aria-label="Permalink to &quot;Workflow（REST，\`/api/ai\`）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>GET/POST</td><td><code>/workflows</code></td><td>列表 / 创建</td></tr><tr><td>GET/PUT/DELETE</td><td><code>/workflows/:id</code></td><td>详情 / 更新 / 删除</td></tr><tr><td>POST</td><td><code>/workflows/:id/publish</code></td><td>发布</td></tr><tr><td>GET</td><td><code>/workflows/:id/versions</code></td><td>版本列表</td></tr><tr><td>POST</td><td><code>/workflows/:id/execute</code></td><td>手动执行（JWT）</td></tr><tr><td>POST</td><td><code>/workflows/invoke/:slugOrId</code></td><td>外部集成执行（<code>X-API-Key</code> / <code>X-Workflow-Key</code>）</td></tr><tr><td>GET</td><td><code>/workflows/invoke/executions/:id</code></td><td>invoke 执行查询</td></tr><tr><td>GET</td><td><code>/workflow-executions</code></td><td>执行列表</td></tr><tr><td>GET</td><td><code>/workflow-executions/:id</code></td><td>执行详情</td></tr><tr><td>POST</td><td><code>/workflow-executions/:id/resume</code></td><td>HITL 恢复</td></tr><tr><td>POST</td><td><code>/workflow-executions/:id/continue</code></td><td>多轮继续</td></tr><tr><td>*</td><td><code>/webhooks/*path</code></td><td>Webhook 触发</td></tr></tbody></table><hr><h2 id="八、相关文档" tabindex="-1">八、相关文档 <a class="header-anchor" href="#八、相关文档" aria-label="Permalink to &quot;八、相关文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>内容</th></tr></thead><tbody><tr><td><a href="./agent.html">agent.md</a></td><td>Chat 专家 Agent 详解</td></tr><tr><td><a href="./agent-workflow.html">agent-workflow.md</a></td><td>工作流编排完整指南</td></tr><tr><td><a href="./ai-shared.html">ai-shared.md</a></td><td>共享包 API 与类型</td></tr><tr><td><a href="./tool.html">tool.md</a></td><td>工具注册与扩展</td></tr><tr><td><a href="./mcp.html">mcp.md</a></td><td>MCP 协议与 Server</td></tr><tr><td><a href="./events.html">events.md</a></td><td>事件协议完整清单</td></tr><tr><td><a href="./design/README.html">design/</a></td><td>产品设计：线框图、交互流、运行时图</td></tr><tr><td><a href="./README.html">README.md</a></td><td>快速开始与文档索引</td></tr></tbody></table>`,73)])])}const u=e(r,[["render",s]]);export{g as __pageData,u as default};
